package com.subhash.chatlauncher

import android.content.Context
import android.graphics.Typeface
import androidx.compose.ui.text.font.FontFamily
import java.io.File
import java.util.zip.GZIPInputStream
import android.util.Base64

// Nunito (SIL Open Font License 1.1, https://openfontlicense.org) embedded
// gzipped+base64 so the font ships without a binary resource. Decoded once to
// the app cache at first use; falls back to the system sans on any failure.
object RoundedTypeface {
    @Volatile private var cached: FontFamily? = null

    fun load(context: Context): FontFamily {
        cached?.let { return it }
        return try {
            val b64 = buildString { for (p in PARTS) append(p) }
            val bytes = GZIPInputStream(Base64.decode(b64, Base64.DEFAULT).inputStream()).readBytes()
            val f = File(context.cacheDir, "nunito.ttf")
            if (!f.exists() || f.length() != bytes.size.toLong()) f.writeBytes(bytes)
            FontFamily(Typeface.createFromFile(f)).also { cached = it }
        } catch (e: Exception) {
            FontFamily.SansSerif
        }
    }

    private val PARTS = arrayOf(
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
    )
}
